'@
$SupportBytes = [Convert]::FromBase64String($SupportPayload)
$SupportHasher = [Security.Cryptography.SHA256]::Create()
try {
    $SupportHash = [BitConverter]::ToString($SupportHasher.ComputeHash($SupportBytes)).Replace('-', '').ToLowerInvariant()
} finally { $SupportHasher.Dispose() }
if ($SupportHash -ne '38fef8d92dfa14a049608799b04a84e59f09c8a4e84020631fa2f8aa559daf14') { throw 'Toolkit checksum mismatch. Nothing executed.' }
$SupportDirectory = Join-Path $env:LOCALAPPDATA 'WindowsSupport\Releases\38fef8d92dfa'
New-Item -ItemType Directory -Path $SupportDirectory -Force | Out-Null
$SupportScript = Join-Path $SupportDirectory 'WindowsSupport.ps1'
if (Test-Path -LiteralPath $SupportScript) {
    if ((Get-FileHash -LiteralPath $SupportScript -Algorithm SHA256).Hash.ToLowerInvariant() -ne $SupportHash) {
        throw 'An existing release has changed. It was not overwritten.'
    }
} else { [IO.File]::WriteAllBytes($SupportScript, $SupportBytes) }
$SupportTicket = Read-Host 'Ticket ID (letters, digits, underscores/hyphens; blank = General)'
if ([string]::IsNullOrWhiteSpace($SupportTicket)) { $SupportTicket = 'General' }
& $SupportScript -TicketId $SupportTicket
